import { jsonResponse } from "@cyspbot/http/problem-details";
import { readRequestBodyUpTo } from "@cyspbot/http/request-body";
import { normalizeInstallationAccessTokenRequest } from "./installation-access-token-request.ts";
import type { TokenExchangeRequestRuntime } from "./dependencies.ts";
import type { InstallationAccessTokenIssuanceFailureReason } from "./policy/installation-access-token-issuance.ts";

const maxTokenExchangeBodyBytes = 64 * 1024;
const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const githubInstallationAccessTokenType = "urn:chikachow:github-app-installation-access-token";
const oidcIdTokenType = "urn:ietf:params:oauth:token-type:id_token";
const unknownRateLimitKey = "unknown";
const unsupportedInvalidTargetParameters = ["audience"];
const unsupportedInvalidRequestParameters = [
  "actor_token",
  "actor_token_type",
  "authorization_details",
  "client_assertion",
  "client_assertion_type",
  "client_id",
  "client_secret",
];

export function tokenExchangeMethodNotAllowedResponse(): Response {
  return oauthErrorResponse(400, "invalid_request");
}

export async function handleTokenExchangeRequest(
  request: Request,
  runtime: TokenExchangeRequestRuntime,
): Promise<Response> {
  const rateLimit = await runtime.rateLimit(tokenExchangeRateLimitKey(request));

  if (!rateLimit) {
    return oauthErrorResponse(429, "temporarily_unavailable");
  }

  if (request.headers.has("authorization")) {
    return oauthErrorResponse(401, "invalid_client", {
      "www-authenticate": wwwAuthenticateChallenge(request.headers.get("authorization")),
    });
  }

  if (!isFormUrlEncodedContentType(request.headers.get("content-type"))) {
    return oauthErrorResponse(400, "invalid_request");
  }

  const body = await readRequestBodyUpTo(request, maxTokenExchangeBodyBytes);

  if (!body.ok) {
    return oauthErrorResponse(body.status, "invalid_request");
  }

  const form = new URLSearchParams(new TextDecoder().decode(body.bytes));
  const grantType = singleFormValue(form, "grant_type");
  const requestedTokenType = singleFormValue(form, "requested_token_type");
  const subjectToken = singleFormValue(form, "subject_token");
  const subjectTokenType = singleFormValue(form, "subject_token_type");
  const tokenRequestOptions = parseInstallationAccessTokenRequestOptions(form);

  if (grantType === null) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (grantType !== tokenExchangeGrantType) {
    return oauthErrorResponse(400, "unsupported_grant_type");
  }

  if (subjectToken === null || subjectToken.length === 0 || subjectTokenType === null) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (subjectTokenType !== oidcIdTokenType) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (requestedTokenType !== githubInstallationAccessTokenType) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (!tokenRequestOptions.ok) {
    return oauthErrorResponse(400, tokenRequestOptions.error);
  }

  const tokenRequest = normalizeInstallationAccessTokenRequest(tokenRequestOptions.options);

  if (!tokenRequest.ok) {
    return oauthErrorResponse(400, tokenRequest.error);
  }

  const authentication = await runtime.authenticateIdToken({
    request,
    subjectToken,
  });

  if (!authentication.ok) {
    const failure = oauthErrorForAuthenticationFailure(authentication.reason);

    return oauthErrorResponse(failure.status, failure.error, authentication.responseHeaders);
  }

  const result = await runtime.issueInstallationAccessToken(
    authentication.context,
    tokenRequest.tokenRequest,
  );

  if (!result.ok) {
    const failure = oauthErrorForIssuanceFailure(result.reason);

    return oauthErrorResponse(failure.status, failure.error);
  }

  return oauthTokenResponse({
    access_token: result.token,
    expires_in: expiresInSeconds(result.expiresAt, runtime.now()),
    issued_token_type: githubInstallationAccessTokenType,
    scope: tokenRequest.tokenRequest.scope,
    token_type: "Bearer",
  });
}

function isFormUrlEncodedContentType(contentType: string | null): boolean {
  if (contentType === null) {
    return false;
  }

  return contentType.split(";", 1)[0]?.trim().toLowerCase() === "application/x-www-form-urlencoded";
}

function singleFormValue(form: URLSearchParams, key: string): string | null {
  const values = nonEmptyFormValues(form, key);

  if (values.length !== 1) {
    return null;
  }

  return values[0] ?? null;
}

function optionalSingleFormValue(
  form: URLSearchParams,
  key: string,
): { ok: true; value: string | null } | { ok: false } {
  const values = nonEmptyFormValues(form, key);

  if (values.length === 0) {
    return { ok: true, value: null };
  }

  if (values.length !== 1) {
    return { ok: false };
  }

  return { ok: true, value: values[0] ?? null };
}

function hasNonEmptyFormValue(form: URLSearchParams, key: string): boolean {
  return nonEmptyFormValues(form, key).length > 0;
}

function nonEmptyFormValues(form: URLSearchParams, key: string): string[] {
  return form.getAll(key).filter((value) => value.length > 0);
}

function wwwAuthenticateChallenge(authorization: string | null): string {
  const scheme = authorization?.split(/\s+/u, 1)[0];

  if (scheme !== undefined && /^[A-Za-z][A-Za-z0-9!#$%&'*+.^_`|~-]*$/u.test(scheme)) {
    return `${scheme} realm="cyspbot"`;
  }

  return 'Basic realm="cyspbot"';
}

function optionalTokenRequestFormValue(
  form: URLSearchParams,
  key: string,
  blankError: string,
): { ok: true; value: string | null } | { error: string; ok: false } {
  const parsed = optionalSingleFormValue(form, key);

  if (!parsed.ok) {
    return { error: "invalid_request", ok: false };
  }

  if (parsed.value === null) {
    return { ok: true, value: null };
  }

  if (parsed.value.trim().length === 0) {
    return { error: blankError, ok: false };
  }

  return { ok: true, value: parsed.value };
}

function requiredResourceFormValue(
  form: URLSearchParams,
): { ok: true; value: string } | { error: "invalid_target"; ok: false } {
  const value = singleFormValue(form, "resource");

  if (value === null || value.trim().length === 0) {
    return { error: "invalid_target", ok: false };
  }

  return { ok: true, value };
}

function parseInstallationAccessTokenRequestOptions(form: URLSearchParams):
  | {
      ok: true;
      options: {
        resource: string;
        scope: string | null;
      };
    }
  | { error: string; ok: false } {
  if (
    unsupportedInvalidRequestParameters.some((parameter) => hasNonEmptyFormValue(form, parameter))
  ) {
    return { error: "invalid_request", ok: false };
  }

  if (
    unsupportedInvalidTargetParameters.some((parameter) => hasNonEmptyFormValue(form, parameter))
  ) {
    return { error: "invalid_target", ok: false };
  }

  const scope = optionalTokenRequestFormValue(form, "scope", "invalid_scope");
  const resource = requiredResourceFormValue(form);

  if (!scope.ok) {
    return { error: scope.error, ok: false };
  }

  if (!resource.ok) {
    return { error: resource.error, ok: false };
  }

  return {
    ok: true,
    options: {
      resource: resource.value,
      scope: scope.value,
    },
  };
}

function oauthTokenResponse(body: Record<string, number | string>): Response {
  return jsonResponse(body, {
    headers: {
      "cache-control": "no-store",
      pragma: "no-cache",
    },
    status: 200,
  });
}

function oauthErrorResponse(status: number, error: string, headers?: HeadersInit): Response {
  const responseHeaders = new Headers(headers);
  responseHeaders.set("cache-control", "no-store");
  responseHeaders.set("pragma", "no-cache");

  return jsonResponse(
    { error },
    {
      headers: responseHeaders,
      status,
    },
  );
}

function oauthErrorForAuthenticationFailure(
  reason: "invalid_token" | "oidc_internal_failure" | "oidc_provider_failure",
): { error: string; status: number } {
  switch (reason) {
    case "invalid_token":
      return { error: "invalid_request", status: 400 };
    case "oidc_internal_failure":
      return { error: "server_error", status: 500 };
    case "oidc_provider_failure":
      return { error: "temporarily_unavailable", status: 503 };
  }
}

function oauthErrorForIssuanceFailure(reason: InstallationAccessTokenIssuanceFailureReason): {
  error: string;
  status: number;
} {
  switch (reason) {
    case "internal_failure":
      return { error: "server_error", status: 500 };
    case "requested_permissions_unsupported":
      return { error: "invalid_scope", status: 400 };
    case "subject_token_unacceptable":
      return { error: "invalid_request", status: 400 };
    case "target_unsupported":
      return { error: "invalid_target", status: 400 };
    case "upstream_failure":
      return { error: "server_error", status: 502 };
    case "upstream_unavailable":
      return { error: "temporarily_unavailable", status: 503 };
  }
}

function expiresInSeconds(expiresAt: string, now: Date): number {
  const expiresAtMs = Date.parse(expiresAt);

  if (Number.isNaN(expiresAtMs)) {
    return 0;
  }

  return Math.max(0, Math.floor((expiresAtMs - now.getTime()) / 1000));
}

function tokenExchangeRateLimitKey(request: Request): string {
  return (
    request.headers.get("cf-connecting-ip") ??
    request.headers.get("x-forwarded-for")?.split(",", 1)[0]?.trim() ??
    unknownRateLimitKey
  );
}
import type { GitHubAppEnv } from "@cyspbot/github/app";
import type { TokenIssuancePolicy } from "./policy/token-issuance-policy.ts";

export interface TokenExchangeApplication {
  readonly githubApp: GitHubAppEnv;
  readonly tokenIssuancePolicy: TokenIssuancePolicy;
}
import {
  createInstallationAccessTokenForRepositoryName,
  GitHubAppConfigurationError,
  resolveInstallationForRepository,
} from "@cyspbot/github/app";
import {
  GitHubApiError,
  GitHubApiTransportError,
  type GitHubApiDependencies,
} from "@cyspbot/github/http";
import type { AuthenticatedContext } from "../authentication.ts";
import type { InstallationAccessTokenRequest } from "../installation-access-token-request.ts";
import type { TokenExchangeApplication } from "../token-exchange-application.ts";
import {
  tokenIssuancePolicyPermits,
  tokenIssuancePolicySupportsRequestedPermissions,
  tokenIssuancePolicySupportsTarget,
} from "./token-issuance-policy.ts";

export type InstallationAccessTokenIssuanceFailureReason =
  | "internal_failure"
  | "requested_permissions_unsupported"
  | "subject_token_unacceptable"
  | "target_unsupported"
  | "upstream_failure"
  | "upstream_unavailable";

export type InstallationAccessTokenIssuanceResult =
  | { expiresAt: string; ok: true; token: string }
  | { ok: false; reason: InstallationAccessTokenIssuanceFailureReason };

export async function issueInstallationAccessTokenForContext(
  application: TokenExchangeApplication,
  authenticationContext: AuthenticatedContext,
  installationAccessTokenRequest: InstallationAccessTokenRequest,
  dependencies: GitHubApiDependencies,
): Promise<InstallationAccessTokenIssuanceResult> {
  const { verifiedSubjectToken } = authenticationContext;
  const policyPermitted = tokenIssuancePolicyPermits(
    application.tokenIssuancePolicy,
    verifiedSubjectToken,
    installationAccessTokenRequest,
  );

  if (!policyPermitted) {
    const targetSupported = tokenIssuancePolicySupportsTarget(
      application.tokenIssuancePolicy,
      installationAccessTokenRequest,
    );
    const requestedPermissionsSupported =
      targetSupported &&
      tokenIssuancePolicySupportsRequestedPermissions(
        application.tokenIssuancePolicy,
        installationAccessTokenRequest,
      );

    console.error({
      error: {
        message: "Token Issuance Policy did not permit Installation Access Token Issuance",
        name: "Error",
        status: undefined,
      },
      event: "installation_access_token_issuance_failed",
      installation_access_token_request: installationAccessTokenRequestLogFields(
        installationAccessTokenRequest,
      ),
      subject_token: subjectTokenLogFields(authenticationContext),
      target_installation: {
        id: undefined,
      },
      token_issuance_policy: {
        permitted: false,
      },
    });

    return {
      ok: false,
      reason: !targetSupported
        ? "target_unsupported"
        : !requestedPermissionsSupported
          ? "requested_permissions_unsupported"
          : "subject_token_unacceptable",
    };
  }

  let targetInstallationId: number | undefined;

  try {
    const requestedResourceName = `${installationAccessTokenRequest.resource.owner}/${installationAccessTokenRequest.resource.repository}`;
    const targetInstallation = await resolveInstallationForRepository(
      application.githubApp,
      requestedResourceName,
      dependencies,
    );
    targetInstallationId = targetInstallation.id;
    const installationAccessToken = await createInstallationAccessTokenForRepositoryName(
      application.githubApp,
      targetInstallation.id,
      installationAccessTokenRequest.resource.repository,
      { ...installationAccessTokenRequest.permissions },
      dependencies,
    );

    console.info({
      event: "installation_access_token_issuance_succeeded",
      expires_at: installationAccessToken.expiresAt,
      installation_access_token_request: installationAccessTokenRequestLogFields(
        installationAccessTokenRequest,
      ),
      subject_token: subjectTokenLogFields(authenticationContext),
      target_installation: {
        id: targetInstallation.id,
        repository: requestedResourceName,
      },
      token_issuance_policy: {
        permitted: true,
      },
    });

    return {
      expiresAt: installationAccessToken.expiresAt,
      ok: true,
      token: installationAccessToken.token,
    };
  } catch (error) {
    const reason = reasonForInstallationAccessTokenIssuanceError(error);

    console.error({
      error: {
        message: logMessageForInstallationAccessTokenIssuanceError(error),
        name: error instanceof Error ? error.name : typeof error,
        status: error instanceof GitHubApiError ? error.upstreamStatus : undefined,
      },
      event: "installation_access_token_issuance_failed",
      installation_access_token_request: installationAccessTokenRequestLogFields(
        installationAccessTokenRequest,
      ),
      subject_token: subjectTokenLogFields(authenticationContext),
      target_installation: {
        id: targetInstallationId,
      },
      token_issuance_policy: {
        permitted: true,
      },
    });

    return { ok: false, reason };
  }
}

function reasonForInstallationAccessTokenIssuanceError(
  error: unknown,
): InstallationAccessTokenIssuanceFailureReason {
  if (error instanceof GitHubApiTransportError) {
    return "upstream_unavailable";
  }

  if (error instanceof GitHubApiError) {
    if (error.rateLimited || error.status === 503) {
      return "upstream_unavailable";
    }

    if (error.status === 400 || error.status === 401 || error.status === 422) {
      return "internal_failure";
    }

    if (error.status === 403 || error.status === 404 || error.status >= 500) {
      return "upstream_failure";
    }
  }

  return "internal_failure";
}

function logMessageForInstallationAccessTokenIssuanceError(error: unknown): string {
  if (
    error instanceof GitHubApiError ||
    error instanceof GitHubApiTransportError ||
    error instanceof GitHubAppConfigurationError
  ) {
    return error.message;
  }

  return "unexpected Installation Access Token Issuance error";
}

function subjectTokenLogFields(
  authenticationContext: AuthenticatedContext,
): Record<string, unknown> {
  return {
    issuer: authenticationContext.verifiedSubjectToken.issuer,
    resolved_key_id: authenticationContext.verificationEvidence.resolvedKeyId,
    sub: authenticationContext.verifiedSubjectToken.claims.sub,
    subject_token_type: "id_token",
  };
}

function installationAccessTokenRequestLogFields(
  installationAccessTokenRequest: InstallationAccessTokenRequest,
): Record<string, unknown> {
  return {
    permissions: installationAccessTokenRequest.permissions,
    resource: installationAccessTokenRequest.resource.href,
    scope: installationAccessTokenRequest.scope,
  };
}

