concurrency:
  group: ${{ github.workflow }}
  cancel-in-progress: false

jobs:
  update:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
          submodules: recursive
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version-file: src/github-app-token-broker/.nvmrc
      - name: Check production endpoint configuration
        run: node --run endpoint:check
        env:
          TOKEN_BROKER_URL: ${{ vars.TOKEN_BROKER_URL }}
      - name: Exchange GitHub Actions identity for deployment-repository token
        id: broker
        uses: chikachow/cyspbot-app-token-action@bf8d299cd20f755c47feb733e3c0f56331a4b49e # v0.0.12
        with:
          cyspbot-token-url: ${{ vars.TOKEN_BROKER_URL }}
          resource: https://api.github.com/repos/chikachow/github-app-token-broker-deploy
          scope: contents:write pull_requests:write
      - name: Update accepted public source pin
        id: update
        run: .github/workflows/update-github-app-token-broker/update-submodule.sh
      - name: Validate updated pin contract
        run: node --run source-pin:check
      - name: Prepare pull request body
        run: >-
          .github/workflows/update-github-app-token-broker/prepare-pull-request-body.sh
          "${{ steps.update.outputs.old_sha }}"
          "${{ steps.update.outputs.new_sha }}"
          pr-body.md
      - name: Create source update pull request
        uses: peter-evans/create-pull-request@5f6978faf089d4d20b00c7766989d076bb2fc7f1 # v8.1.1
        with:
          token: ${{ steps.broker.outputs.token }}
          commit-message: "feat: update github-app-token-broker"
          title: "feat: update github-app-token-broker"
          body-path: pr-body.md
          branch: actions/update-github-app-token-broker
          add-paths: |
            .gitmodules
            src/github-app-token-broker
          sign-commits: true
