      expect(response.status).toBe(500);
      expect(consoleError).toHaveBeenCalledWith("webhook_receiver_not_configured", {
        occurred_at: now.toISOString(),
      });
      await response.body?.cancel();
    } finally {
      vi.useRealTimers();
      consoleError.mockRestore();
    }
  });
});
