import { WorkerEntrypoint } from "cloudflare:workers";

import {
  createTokenExchangeWorkerEntrypoint,
  createTokenExchangeWorkerService,
  type GitHubAppInstallationTokenRpcInput,
} from "@github-app-token-broker/worker";
import { requestGithubAppInstallationToken } from "@github-app-token-broker/worker";
import {
  fetchTokenExchange,
  testEnv,
  testTokenExchangeComposition,
  testTokenExchangeWorkerRuntimeDependencies,
  tokenExchangeRequestBody,
} from "./support/worker.ts";
import { createOidcToken } from "./support/oidc-token.ts";
import { testPrivateKeyPem } from "./support/rsa-test-key-pair.ts";
import { fetchGitHubTestDouble } from "./support/github-api.ts";
import { fetchOidcRemoteDocumentResponseTestDouble } from "./support/oidc.ts";
import { testNow, testRepository } from "./support/constants.ts";

describe("github-app-token-broker RPC", () => {
  it("issues a policy-authorized repository-scoped installation token", async () => {
    const form = new URLSearchParams(await tokenExchangeRequestBody());
    const Entrypoint = createTokenExchangeWorkerEntrypoint(
      testTokenExchangeComposition,
      testTokenExchangeWorkerRuntimeDependencies,
    );
    const entrypoint = new Entrypoint({} as ExecutionContext, testEnv);

    expect(entrypoint).toBeInstanceOf(WorkerEntrypoint);

    await expect(
      entrypoint.requestGithubAppInstallationToken({
        resource: `https://api.github.com/repos/${testRepository}`,
        scope: "contents:write pull_requests:write",
        subjectToken: form.get("subject_token") ?? "",
      }),
    ).resolves.toEqual({
      accessToken: "ghs_test_token",
      expiresAt: "2030-01-01T00:00:00Z",
      ok: true,
    });
  });

  it("returns invalid_request and does not mint when policy rejects the subject token", async () => {
    const fetchExternal = vi.fn<typeof fetch>((input, init) => {
      const request = new Request(input, init);

      return new URL(request.url).hostname === "token.actions.githubusercontent.com"
        ? fetchOidcRemoteDocumentResponseTestDouble(request)
        : fetchGitHubTestDouble(input, init);
    });
    const service = createTokenExchangeWorkerService(testTokenExchangeComposition, {
      fetch: fetchExternal,
      now: () => testNow,
    });
    const subjectToken = await createOidcToken(testPrivateKeyPem, { event_name: "push" });

    await expect(
      service.requestGithubAppInstallationToken(
        {
          resource: `https://api.github.com/repos/${testRepository}`,
          scope: "contents:write pull_requests:write",
          subjectToken,
        },
        testEnv,
      ),
    ).resolves.toEqual({ error: "invalid_request", ok: false });

    expect(
      fetchExternal.mock.calls.filter(
        ([input]) => new URL(new Request(input).url).hostname === "api.github.com",
      ),
    ).toHaveLength(0);
  });

  it("returns invalid_request for malformed structured-clone input before authentication", async () => {
    const exchange = { exchange: vi.fn() };

    await expect(
      requestGithubAppInstallationToken(
        {
          resource: `https://api.github.com/repos/${testRepository}`,
          scope: "contents:write",
        } as unknown as GitHubAppInstallationTokenRpcInput,
        { exchange, githubApp: testEnv },
      ),
    ).resolves.toEqual({ error: "invalid_request", ok: false });

    expect(exchange.exchange).not.toHaveBeenCalled();
  });

  it("preserves the existing HTTP token-exchange contract", async () => {
    const response = await fetchTokenExchange("https://example.test/token", {
      body: await tokenExchangeRequestBody(),
      headers: { "content-type": "application/x-www-form-urlencoded" },
      method: "POST",
    });

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({
      access_token: "ghs_test_token",
      token_type: "Bearer",
    });
  });
});
