        typeof allowedAudience !== "string" || allowedAudience.trim().length === 0,
    )
  ) {
    throw new Error("Workload identity binding allowedAudiences must contain non-empty strings.");
  }

  return { allowedAudiences, subject: validatedSubject };
}

