import { env, exports } from "cloudflare:workers";
import { describe, expect, it } from "vitest";
import { githubInstallationAccessTokenType } from "../constants.ts";
import { createTokenExchangeRequestBody } from "../oidc-token.ts";

describe("deployment Worker entrypoint", () => {
  it("exchanges an exact permitted token and denies a changed workflow before GitHub", async () => {
    const request = (workflow_ref: string) =>
      createTokenExchangeRequestBody(env.OIDC_TEST_PRIVATE_KEY, {
        claims: {
          event_name: "workflow_dispatch",
          ref: "refs/heads/main",
          ref_type: "branch",
          repository: "chikachow/github-app-token-broker",
          workflow_ref,
        },
        form: {
          resource: "https://api.github.com/repos/chikachow/github-app-token-broker",
          scope: "contents:write pull_requests:write",
        },
        tokenOptions: { audience: "https://cyspbot.chikachow.org" },
      });
    const first = await exports.default.fetch("https://example.test/token", {
      body: await request(
        "chikachow/github-app-token-broker/.github/workflows/pnpm-up.yml@refs/heads/main",
      ),
      headers: { "content-type": "application/x-www-form-urlencoded" },
      method: "POST",
    });
    expect(first.status).toBe(200);
    expect(first.headers.get("cache-control")).toBe("no-store");
    expect(first.headers.get("pragma")).toBe("no-cache");
    await expect(first.json()).resolves.toEqual({
      access_token: "ghs_deployment_test",
      expires_in: expect.any(Number),
      issued_token_type: githubInstallationAccessTokenType,
      scope: "contents:write pull_requests:write",
      token_type: "Bearer",
    });
    const denied = await exports.default.fetch("https://example.test/token", {
      body: await request(
        "chikachow/github-app-token-broker/.github/workflows/changed.yml@refs/heads/main",
      ),
      headers: { "content-type": "application/x-www-form-urlencoded" },
      method: "POST",
    });
    expect(denied.status).toBe(400);
    expect(denied.headers.get("cache-control")).toBe("no-store");
    expect(denied.headers.get("pragma")).toBe("no-cache");
    await expect(denied.json()).resolves.toEqual({ error: "invalid_request" });
  });
});
