import { testGithubActionsIssuer } from "../oidc-token.ts";
import { testPublicJwk } from "../rsa-test-key-pair.ts";

let githubRequestCount = 0;

export async function outboundService(request: Request): Promise<Response> {
  if (
    request.url === `${testGithubActionsIssuer}/.well-known/openid-configuration` &&
    request.method === "GET"
  )
    return Response.json({
      id_token_signing_alg_values_supported: ["RS256"],
      issuer: testGithubActionsIssuer,
      jwks_uri: `${testGithubActionsIssuer}/.well-known/jwks`,
    });
  if (request.url === `${testGithubActionsIssuer}/.well-known/jwks` && request.method === "GET")
    return Response.json({ keys: [testPublicJwk] });

  assertGitHubHeaders(request);

  if (
    request.url === "https://api.github.com/repos/chikachow/github-app-token-broker/installation" &&
    request.method === "GET" &&
    githubRequestCount === 0
  ) {
    githubRequestCount += 1;
    return Response.json({ account: { login: "chikachow" }, id: 67890 });
  }

  if (
    request.url === "https://api.github.com/app/installations/67890/access_tokens" &&
    request.method === "POST" &&
    githubRequestCount === 1
  ) {
    assertHeader(request, "content-type", "application/json");
    assertHeader(request, "x-github-stateless-s2s-token", "enabled");
    const body: unknown = await request.json();
    const expected = JSON.stringify({
      permissions: { contents: "write", pull_requests: "write" },
      repositories: ["github-app-token-broker"],
    });

    if (JSON.stringify(body) !== expected) {
      throw new Error(`unexpected GitHub token request body: ${JSON.stringify(body)}`);
    }

    githubRequestCount += 1;
    return Response.json(
      {
        expires_at: "2030-01-01T00:00:00Z",
        permissions: { contents: "write", pull_requests: "write" },
        token: "ghs_deployment_test",
      },
      { status: 201 },
    );
  }

  throw new Error(`unexpected outbound request: ${request.method} ${request.url}`);
}

function assertGitHubHeaders(request: Request): void {
  assertHeader(request, "accept", "application/vnd.github+json");
  assertHeader(request, "user-agent", "github-app-token-broker");
  assertHeader(request, "x-github-api-version", "2022-11-28");

  if (!request.headers.get("authorization")?.startsWith("Bearer ")) {
    throw new Error("GitHub request is missing Bearer authorization");
  }
}

function assertHeader(request: Request, name: string, expected: string): void {
  const actual = request.headers.get(name);

  if (actual !== expected) {
    throw new Error(`unexpected ${name} header: ${actual ?? "<missing>"}`);
  }
}
