  ],
};

export function validateSourcePin({ requireAccepted = false } = {}) {
  const gitlink = git(repositoryRoot, ["rev-parse", ":src/github-app-token-broker"]);
  const checkout = git(sourceRoot, ["rev-parse", "HEAD"]);
  const url = git(repositoryRoot, [
    "config",
    "-f",
    ".gitmodules",
    "--get",
    "submodule.src/github-app-token-broker.url",
  ]);
  const branch = git(repositoryRoot, [
    "config",
    "-f",
    ".gitmodules",
    "--get",
    "submodule.src/github-app-token-broker.branch",
  ]);

  require(gitlink === checkout, "The source checkout must match the committed gitlink.");
  require(url === sourceRepository, "The source URL is not the authoritative public repository.");
  require(branch === "main", "The source must track accepted main.");
  for (const path of requiredContractPaths) {
    git(sourceRoot, ["cat-file", "-e", `${checkout}:${path}`]);
  }
  for (const path of removedConfiguredCompositionPaths) {
    require(!gitObjectExists(
      checkout,
      path,
    ), `The public source still owns deployment composition at ${path}.`);
  }
  requireSourceContent(checkout, "workers/github-app-token-broker/src/worker.ts", [
    "createTokenExchangeWorker",
    "TOKEN_BROKER_AUDIENCE",
  ]);
  requireSourceContent(checkout, "workers/github-app-token-broker/src/index.ts", [
    "createTokenExchangeWorker",
    "TokenExchangeComposition",
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/src/index.ts", [
    "createConfiguredTokenExchangeWorker",
    "export default",
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/src/worker.ts", [
    "env.TOKEN_BROKER_URL",
  ]);
  requireSourceContent(checkout, "workers/github-app-token-broker/wrangler.jsonc", [
    '"main": "src/generic-worker.ts"',
    '"TOKEN_BROKER_AUDIENCE"',
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/wrangler.jsonc", [
    '"TOKEN_BROKER_URL"',
  ]);
  for (const [workflow, requiredText] of Object.entries(sourceWorkflowContracts)) {
    requireSourceContent(checkout, workflow, requiredText);
    forbidSourceContent(checkout, workflow, [
      "cyspbot-token-url",
      "github-actions-token-exchange.ts",
      "TOKEN_BROKER_AUDIENCE",
    ]);
  }
  forbidSourceContent(checkout, ".github/workflows/pnpm-up.yml", ["resource:", "scope:"]);

  if (requireAccepted) {
    const shallow = git(sourceRoot, ["rev-parse", "--is-shallow-repository"]) === "true";
    git(sourceRoot, [
