function isOAuthScopePermissionName(name: string): boolean {
  if (name.length === 0) {
    return false;
  }

  for (const character of name) {
    const codePoint = character.codePointAt(0);

    if (
      codePoint === undefined ||
      codePoint === 0x3a ||
      !(
        codePoint === 0x21 ||
        (codePoint >= 0x23 && codePoint <= 0x5b) ||
        (codePoint >= 0x5d && codePoint <= 0x7e)
      )
    ) {
      return false;
    }
  }

  return true;
}

function isGitHubPathSegment(value: string | undefined): value is string {
  return value !== undefined && /^[A-Za-z0-9_.-]+$/u.test(value);
}

function isConstructibleGitHubPathSegment(value: unknown): value is string {
  return typeof value === "string" && value !== "." && value !== ".." && isGitHubPathSegment(value);
}

