    response = await dependencies.fetch(requestUrl, {
      ...init,
      headers: requestHeaders,
    });
  } catch {
    throw new GitHubApiTransportError(`GitHub API request failed: ${path}`);
  }

  if (!response.ok) {
    throw new GitHubApiError(
      response.status,
