  let responseBody: unknown;

  try {
    responseBody = JSON.parse(responseText);
  } catch {
    throw invalidGitHubApiResponse(path, response.status);
  }

  const parsed = responseSchema.safeParse(responseBody);

  if (!parsed.success) {
    throw invalidGitHubApiResponse(path, response.status);
  }

  return parsed.data;

