const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const requestedTokenType = "urn:ietf:params:oauth:token-type:access_token";
const subjectTokenType = "urn:ietf:params:oauth:token-type:id_token";

/** The Subject-Token Audience accepted by the broker's OIDC authenticator. */
const subjectTokenAudience = "https://cyspbot.chikachow.org";

/** The broker's RFC 8693 Token Endpoint. */
const tokenEndpoint = "https://cyspbot.chikachow.org/token";

export interface GitHubAppInstallationTokenRequest {
  /** Canonical GitHub API Repository Resource where the token will be used. */
  readonly resource: string;
  /** Explicit GitHub App permission requests, in the broker's scope syntax. */
  readonly scope: string;
}

interface WorkloadIdentityIssuerBinding {
  issueToken(audience: string): unknown;
}

/**
 * Acts as the OAuth Client for the broker's RFC 8693 Token Endpoint. It first
 * obtains a Workload Identity Token through the CWI RPC binding, then presents
 * that workload identity assertion as the RFC 8693 `subject_token` under the
 * broker's OIDC ID Token subject-token profile. The raw OAuth response is
 * returned so callers can handle both success and error responses themselves.
 */
export async function requestGitHubAppInstallationToken(
  env: CyspbotEnv,
  request: GitHubAppInstallationTokenRequest,
): Promise<Response> {
  const resource = requireNonEmptyString(request.resource, "resource");
  const scope = requireNonEmptyString(request.scope, "scope");
  const issuer = requireWorkloadIdentityIssuer(env.WORKLOAD_IDENTITY_ISSUER);
  const issuedToken = await issuer.issueToken(subjectTokenAudience);
  const subjectToken = requireIssuedToken(issuedToken);

  const body = new URLSearchParams({
    grant_type: tokenExchangeGrantType,
    requested_token_type: requestedTokenType,
    resource,
    scope,
    subject_token: subjectToken,
    subject_token_type: subjectTokenType,
  });

  return env.GITHUB_APP_TOKEN_BROKER.fetch(tokenEndpoint, {
    body,
    headers: {
      accept: "application/json",
      "content-type": "application/x-www-form-urlencoded",
    },
    method: "POST",
  });
}

function requireWorkloadIdentityIssuer(value: unknown): WorkloadIdentityIssuerBinding {
  if (
    typeof value !== "object" ||
    value === null ||
    typeof (value as { issueToken?: unknown }).issueToken !== "function"
  ) {
    throw new TypeError("WORKLOAD_IDENTITY_ISSUER must expose issueToken().");
  }

  return value as WorkloadIdentityIssuerBinding;
}

function requireIssuedToken(value: unknown): string {
  if (
    typeof value !== "object" ||
    value === null ||
    typeof (value as { token?: unknown }).token !== "string" ||
    (value as { token: string }).token.length === 0
  ) {
    throw new TypeError("WORKLOAD_IDENTITY_ISSUER returned an invalid IssuedToken.");
  }

  return (value as { token: string }).token;
}

function requireNonEmptyString(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must be a non-empty string.`);
  }

  return value;
}
