import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { parseArgs } from "node:util";

import { repositoryRoot, sourceRoot } from "./deploy-configuration.mjs";

const sourceRepository = "https://github.com/chikachow/github-app-token-broker.git";
const acceptedBaseline = "55331b13ffd1261816ee27df121c7c9ca1cad1bc";
const actionRelease =
  "chikachow/cyspbot-app-token-action@bf8d299cd20f755c47feb733e3c0f56331a4b49e # v0.0.12";
const requiredContractPaths = [
  ".github/workflows/pnpm-up.yml",
  ".github/workflows/run-github-app-token-broker-deploy-update.yml",
  "packages/github/src/installation-access-token-request.ts",
  "packages/oidc/src/provider-registration.ts",
  "packages/token-issuance-policy/src/token-issuance-policy.ts",
  "workers/github-app-token-broker/src/generic-worker.ts",
  "workers/github-app-token-broker/src/index.ts",
  "workers/github-app-token-broker/src/token-exchange.ts",
  "workers/github-app-token-broker/src/worker.ts",
  "workers/github-app-token-broker/wrangler.jsonc",
];
const removedConfiguredCompositionPaths = [
  "workers/github-app-token-broker/src/configured-oidc-provider-registrations.ts",
  "workers/github-app-token-broker/src/configured-token-exchange-composition.ts",
  "workers/github-app-token-broker/src/configured-worker.ts",
  "workers/github-app-token-broker/src/policy/configured-token-issuance-policy.ts",
];
const sourceWorkflowContracts = {
  ".github/workflows/pnpm-up.yml": [actionRelease, "id: cyspbot"],
  ".github/workflows/run-github-app-token-broker-deploy-update.yml": [
    actionRelease,
    "resource: https://api.github.com/repos/chikachow/github-app-token-broker-deploy",
    "scope: actions:write",
  ],
};

export function validateSourcePin({ requireAccepted = false } = {}) {
  const gitlink = git(repositoryRoot, ["rev-parse", ":src/github-app-token-broker"]);
  const checkout = git(sourceRoot, ["rev-parse", "HEAD"]);
  const url = git(repositoryRoot, [
    "config",
    "-f",
    ".gitmodules",
    "--get",
    "submodule.src/github-app-token-broker.url",
  ]);
  const branch = git(repositoryRoot, [
    "config",
    "-f",
    ".gitmodules",
    "--get",
    "submodule.src/github-app-token-broker.branch",
  ]);

  require(gitlink === checkout, "The source checkout must match the committed gitlink.");
  require(url === sourceRepository, "The source URL is not the authoritative public repository.");
  require(branch === "main", "The source must track accepted main.");
  for (const path of requiredContractPaths) {
    git(sourceRoot, ["cat-file", "-e", `${checkout}:${path}`]);
  }
  for (const path of removedConfiguredCompositionPaths) {
    require(!gitObjectExists(
      checkout,
      path,
    ), `The public source still owns deployment composition at ${path}.`);
  }
  requireSourceContent(checkout, "workers/github-app-token-broker/src/worker.ts", [
    "createTokenExchangeWorker",
    "TOKEN_BROKER_AUDIENCE",
  ]);
  requireSourceContent(checkout, "workers/github-app-token-broker/src/index.ts", [
    "createTokenExchangeWorker",
    "TokenExchangeComposition",
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/src/index.ts", [
    "createConfiguredTokenExchangeWorker",
    "export default",
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/src/worker.ts", [
    "env.TOKEN_BROKER_URL",
  ]);
  requireSourceContent(checkout, "workers/github-app-token-broker/wrangler.jsonc", [
    '"main": "src/generic-worker.ts"',
    '"TOKEN_BROKER_AUDIENCE"',
  ]);
  forbidSourceContent(checkout, "workers/github-app-token-broker/wrangler.jsonc", [
    '"TOKEN_BROKER_URL"',
  ]);
  for (const [workflow, requiredText] of Object.entries(sourceWorkflowContracts)) {
    requireSourceContent(checkout, workflow, requiredText);
    forbidSourceContent(checkout, workflow, [
      "cyspbot-token-url",
      "github-actions-token-exchange.ts",
      "TOKEN_BROKER_AUDIENCE",
    ]);
  }
  forbidSourceContent(checkout, ".github/workflows/pnpm-up.yml", ["resource:", "scope:"]);

  if (requireAccepted) {
    const shallow = git(sourceRoot, ["rev-parse", "--is-shallow-repository"]) === "true";
    git(sourceRoot, [
      "fetch",
      ...(shallow ? ["--unshallow"] : []),
      "--no-tags",
      "origin",
      "+refs/heads/main:refs/remotes/origin/main",
    ]);
    git(sourceRoot, ["merge-base", "--is-ancestor", acceptedBaseline, "refs/remotes/origin/main"]);
    git(sourceRoot, ["merge-base", "--is-ancestor", checkout, "refs/remotes/origin/main"]);
  }

  return { branch, commit: checkout };
}

function requireSourceContent(commit, path, requiredText) {
  const content = git(sourceRoot, ["show", `${commit}:${path}`]);
  for (const text of requiredText) {
    require(content.includes(text), `The reviewed source contract is missing ${text} in ${path}.`);
  }
  return content;
}

function forbidSourceContent(commit, path, prohibitedText) {
  const content = git(sourceRoot, ["show", `${commit}:${path}`]);
  for (const text of prohibitedText) {
    require(!content.includes(
      text,
    ), `The reviewed source contract still contains ${text} in ${path}.`);
  }
}

function gitObjectExists(commit, path) {
  try {
    git(sourceRoot, ["cat-file", "-e", `${commit}:${path}`]);
    return true;
  } catch {
    return false;
  }
}

function git(cwd, arguments_) {
  return execFileSync("git", arguments_, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

function require(condition, message) {
  if (!condition) throw new Error(message);
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { values } = parseArgs({
    args: process.argv.slice(2),
    options: { "require-accepted": { type: "boolean", default: false } },
    strict: true,
  });
  const result = validateSourcePin({ requireAccepted: values["require-accepted"] });
  console.log(`Validated source pin ${result.commit} (${result.branch}).`);
}
import assert from "node:assert/strict";
import { test } from "node:test";

import { validateSourcePin } from "./source-pin.mjs";

test("the committed public source pin is internally exact", () => {
  assert.deepEqual(validateSourcePin(), {
    branch: "main",
    commit: "ecbb927887f4215b3932b2f4d9c5dfd4209dcc7c",
  });
});
# Source pin

The deployable source is the public `chikachow/github-app-token-broker`
submodule at `src/github-app-token-broker`.

The accepted source baseline is:

- pull request: <https://github.com/chikachow/github-app-token-broker/pull/8>
- branch: `main`
- merged commit: `55331b13ffd1261816ee27df121c7c9ca1cad1bc`

Production preflight requires the merged PR #8 baseline and the pinned commit
itself to be ancestors of current source `main`. The check depends only on
objects reachable from `main`, so it also works in the shallow submodule checkout
used by the deployment workflow. That is the accepted-source gate; a branch name
or open pull request is not sufficient.

`update-github-app-token-broker.yml` advances the pin to the exact remote `main`
commit and opens a signed update pull request.

This branch pins source commit
`ecbb927887f4215b3932b2f4d9c5dfd4209dcc7c` from
[source PR #12](https://github.com/chikachow/github-app-token-broker/pull/12).
That revision adds the owner-scoped Repository Resource Constraint used by the
current CWI Permit Statement. The deployment branch is ready for source checks
and dry runs. Merge source PR #12 before merging or deploying this deployment
change: production preflight still requires the pinned commit to be reachable
from source `main`.

The pinned source owns the reusable Worker implementation, strict use of the
deployment binding `TOKEN_BROKER_AUDIENCE` as the exact Subject-Token Audience,
portable policy and OIDC Provider Registration Interfaces, source-side action
integrations, and dispatch workflow. This repository owns its reviewed OIDC
Provider Registrations, Token Issuance Policy, and Worker entrypoint. The root
workspace consumes the pinned packages directly; the public repository is also
installed and checked independently with its own lockfile. The Subject-Token Audience is
exactly `https://cyspbot.chikachow.org`. `TOKEN_BROKER_URL` is not a Worker
binding. The separately released `cyspbot-app-token-action`, pinned here at
bundled release commit `bf8d299cd20f755c47feb733e3c0f56331a4b49e`
(`v0.0.12`), uses the same fixed Subject-Token Audience and defaults to
`https://cyspbot.chikachow.org/token` without consulting a request
URL, `Host`, or forwarded headers.

Neither the OIDC Provider Registrations nor Token Issuance Policy is a runtime
override. Changing either requires a reviewed deployment-source change, a new
bundle, and deployment of that artifact.

The pinned source workflows use the independently bundled action release
without a `cyspbot-token-url` override. Its `pnpm-up` workflow relies on the
action's default endpoint, repository resource, and least-privilege scope. Its
deployment-update workflow relies on the default endpoint while explicitly
requesting the deployment repository and `actions:write`. This repository's
own source-update workflow currently supplies its configured endpoint plus an
explicit deployment-repository resource and scope. The deployment validates
the Worker's Subject-Token Audience against the action's Subject-Token Audience
and independently validates the action's effective Token Exchange Endpoint
against the full routed `/token` URL before deployment or an automated source
update. The current production configuration leaves the URL override unset, so
the action uses `https://cyspbot.chikachow.org/token` while the Subject-Token
Audience remains `https://cyspbot.chikachow.org`.

