import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { requireExactKeys, requireRecord } from "./object-validation.mjs";

export const repositoryRoot = resolve(import.meta.dirname, "..");
export const sourceRoot = resolve(repositoryRoot, "src/github-app-token-broker");
export const worker = "github-app-token-broker";

const expectedCompatibilityFlags = [
  "no_nodejs_compat",
  "no_nodejs_compat_v2",
  "no_nodejs_als",
  "disallow_eval_during_startup",
  "global_fetch_strictly_public",
];
const expectedRoutePattern = "cyspbot.chikachow.org/token*";
const expectedTokenAudience = "https://cyspbot.chikachow.org";
const expectedTokenUrl = "https://cyspbot.chikachow.org/token";

export function workerConfigPath() {
  return resolve(repositoryRoot, "config/workers/github-app-token-broker.wrangler.json");
}

export async function validateDeploymentConfiguration(configuration, sourceContract) {
  if (configuration === undefined) {
    configuration = JSON.parse(await readFile(workerConfigPath(), "utf8"));
  }
  if (sourceContract === undefined) sourceContract = await readSourceWranglerContract();

  configuration = requireRecord(configuration, "Production Worker configuration");
  require(configuration.name === worker, "The production Worker name is incorrect.");
  const usesPinnedBrokerSource = configuration.main === "../../src/worker.ts";
  require(usesPinnedBrokerSource, "Production must execute the deployment-owned Worker entrypoint.");
  const preservesCompatibilityDate =
    configuration.compatibility_date === sourceContract.compatibilityDate;
  require(preservesCompatibilityDate, "Production compatibility date must match source.");
  const preservesSourceFlags = arraysEqual(
    configuration.compatibility_flags,
    sourceContract.compatibilityFlags,
  );
  const usesReviewedFlags = arraysEqual(
    configuration.compatibility_flags,
    expectedCompatibilityFlags,
  );
  require(preservesSourceFlags &&
    usesReviewedFlags, "Production compatibility flags must match the reviewed source contract.");
  require(configuration.workers_dev === false, "The production Worker must disable workers.dev.");
  require(configuration.preview_urls === false, "The production Worker must disable preview URLs.");
  validateObservability(configuration.observability);
  const routedTokenUrl = validateRoute(configuration.routes);
  validateRateLimit(configuration.ratelimits);
  validateGitHubAppSecret(configuration.secrets_store_secrets);
  const tokenAudience = validateVariables(configuration.vars);
  require(tokenAudience ===
    expectedTokenAudience, "Production audience binding must match the reviewed deployment contract.");
  require(routedTokenUrl === expectedTokenUrl, "The effective public token URL is incorrect.");
  require(configuration.secrets === undefined, "Production must use the Secrets Store binding.");
}

export async function validateTokenClientConfiguration(
  tokenUrlOverride,
  configuration,
  sourceContract,
) {
  if (configuration === undefined) {
    configuration = JSON.parse(await readFile(workerConfigPath(), "utf8"));
  }

  await validateDeploymentConfiguration(configuration, sourceContract);
  const effectiveTokenUrl = effectiveClientTokenUrl(tokenUrlOverride);
  const routedTokenUrl = validateRoute(configuration.routes);
  require(effectiveTokenUrl ===
    routedTokenUrl, "The effective client token URL must equal the deployment-owned routed /token URL.");
}

export function productionTokenAudience() {
  return expectedTokenAudience;
}

export function productionTokenUrl() {
  return expectedTokenUrl;
}

async function readSourceWranglerContract() {
  const sourceConfiguration = await readFile(
    resolve(sourceRoot, "workers/github-app-token-broker/wrangler.jsonc"),
    "utf8",
  );
  const compatibilityDate = sourceConfiguration.match(/"compatibility_date"\s*:\s*"([^"]+)"/u)?.[1];
  const flagsBlock = sourceConfiguration.match(/"compatibility_flags"\s*:\s*\[([\s\S]*?)\]/u)?.[1];
  const compatibilityFlags =
    flagsBlock === undefined
      ? undefined
      : [...flagsBlock.matchAll(/"([^"]+)"/gu)].map((match) => match[1]);
  const completeContract = compatibilityDate !== undefined && compatibilityFlags !== undefined;
  require(completeContract, "The pinned source Wrangler contract could not be read.");
  require(!/"TOKEN_BROKER_URL"\s*:/u.test(
    sourceConfiguration,
  ), "The pinned source Worker must not bind TOKEN_BROKER_URL.");
  return { compatibilityDate, compatibilityFlags };
}

function validateObservability(observability) {
  observability = requireRecord(observability, "Production observability");
  const logs = requireRecord(observability.logs, "Production log observability");
  const traces = requireRecord(observability.traces, "Production trace observability");
  const fullySampled =
    observability.enabled === true &&
    logs.head_sampling_rate === 1 &&
    traces.enabled === true &&
    traces.head_sampling_rate === 1;
  require(fullySampled, "Production logs and traces must be enabled and fully sampled.");
}

function validateRoute(routes) {
  require(Array.isArray(routes) && routes.length === 1, "The Worker must own exactly one route.");
  const route = requireExactKeys(routes[0], ["pattern", "zone_name"], "Production route");
  const preservesEndpoint =
    route.pattern === expectedRoutePattern && route.zone_name === "chikachow.org";
  require(preservesEndpoint, "The production route must preserve the public token endpoint.");
  const routedTokenUrl = `https://${route.pattern.slice(0, -1)}`;
