import { pathToFileURL } from "node:url";

import { productionTokenUrl } from "./deploy-configuration.mjs";
import { requireExactKeys } from "./object-validation.mjs";

const maximumResponseBytes = 4096;

export async function probeTokenEndpoint(
  endpoint = productionTokenUrl(),
  { attempts = 1, fetch: fetchImplementation = fetch, retryDelayMilliseconds = 5000 } = {},
) {
  const url = requireExactTokenUrl(endpoint);
  let lastError;

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      const response = await fetchImplementation(url, {
        body: new URLSearchParams(),
        headers: { "content-type": "application/x-www-form-urlencoded" },
        method: "POST",
        redirect: "error",
        signal: AbortSignal.timeout(20_000),
      });
      await validateProbeResponse(response);
      return;
    } catch (error) {
      lastError = error;
      if (attempt < attempts)
        await new Promise((resolve) => setTimeout(resolve, retryDelayMilliseconds));
    }
  }

  throw new Error(`POST ${url.href} did not satisfy the broker probe contract.`, {
    cause: lastError,
  });
}

export async function validateProbeResponse(response) {
  if (response.status !== 400) throw new Error(`Expected status 400, received ${response.status}.`);
  if (response.headers.get("cache-control")?.toLowerCase() !== "no-store") {
    throw new Error("Expected Cache-Control: no-store.");
  }
  if (!response.headers.get("content-type")?.toLowerCase().startsWith("application/json")) {
    throw new Error("Expected an application/json OAuth error response.");
  }
  const body = requireExactKeys(
    JSON.parse(await readTextUpTo(response, maximumResponseBytes)),
    ["error"],
    "Probe response",
  );
  if (body.error !== "invalid_request") throw new Error("Expected OAuth invalid_request.");
}

export function resolveProbeEndpoint(endpointOverride) {
  const configuredEndpoint = endpointOverride?.trim();
  return configuredEndpoint === undefined || configuredEndpoint === ""
    ? productionTokenUrl()
    : endpointOverride;
}

function requireExactTokenUrl(value) {
  const url = new URL(value);
  if (
    url.href !== value ||
    url.protocol !== "https:" ||
    url.pathname !== "/token" ||
    url.username !== "" ||
    url.password !== "" ||
    url.search !== "" ||
    url.hash !== ""
  ) {
    throw new Error("The probe endpoint must be an exact credential-free HTTPS /token URL.");
  }
  return url;
}

async function readTextUpTo(response, limit) {
  if (response.body === null) return "";
  const reader = response.body.getReader();
  const chunks = [];
  let length = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      length += value.byteLength;
      if (length > limit) throw new Error(`Probe response exceeded ${limit} bytes.`);
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  const body = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(body);
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const endpoint = resolveProbeEndpoint(process.env.TOKEN_BROKER_URL);
  const attempts = Number.parseInt(process.env.PROBE_ATTEMPTS ?? "1", 10);
  if (!Number.isSafeInteger(attempts) || attempts < 1 || attempts > 30) {
    throw new Error("PROBE_ATTEMPTS must be an integer from 1 through 30.");
  }
  await probeTokenEndpoint(endpoint, { attempts });
  console.log(`POST ${endpoint} satisfied the credential-free broker probe contract.`);
}
import { validateTokenClientConfiguration } from "./deploy-configuration.mjs";

await validateTokenClientConfiguration(process.env.TOKEN_BROKER_URL);
