 38	 * Installation Access Token through the broker's RFC 8693 Token Endpoint.
 39	 */
 40	export async function requestGitHubAppInstallationToken(
 41	  env: CyspbotEnv,
 42	  request: GitHubAppInstallationTokenRequest,
 43	): Promise<GitHubAppInstallationAccessToken> {
 44	  const resource = requireNonEmptyString(request.resource, "resource");
 45	  const scope = requireNonEmptyString(request.scope, "scope");
 46	  const issuer = requireWorkloadIdentityIssuer(env.WORKLOAD_IDENTITY_ISSUER);
 47	  const issuedToken = await issuer.issueToken(env.WORKLOAD_IDENTITY_TOKEN_AUDIENCE);
 48	  const subjectToken = requireIssuedToken(issuedToken);
 49	
 50	  const response = await env.GITHUB_APP_TOKEN_BROKER.fetch(
 51	    env.GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT,
 52	    {
 53	      body: new URLSearchParams({
 54	        grant_type: tokenExchangeGrantType,
 55	        requested_token_type: requestedTokenType,
 56	        resource,
 57	        scope,
 58	        subject_token: subjectToken,
 59	        subject_token_type: subjectTokenType,
 60	      }),
 61	      headers: {
 62	        accept: "application/json",
 63	        "content-type": "application/x-www-form-urlencoded",
 64	      },
 65	      method: "POST",
 66	      redirect: "error",
 67	    },
 68	  );
 69	
 70	  if (!response.ok) {
 71	    throw await readBrokerError(response);
 72	  }
 73	
 74	  return readInstallationAccessToken(response);
