 77	function requireWorkloadIdentityIssuer(value: unknown): WorkloadIdentityIssuerBinding {
 78	  if (!isWorkloadIdentityIssuerBinding(value)) {
 79	    throw new TypeError("WORKLOAD_IDENTITY_ISSUER must expose issueToken().");
 80	  }
