 86	  if (!isRecord(value)) {
 87	    throw new TypeError("WORKLOAD_IDENTITY_ISSUER returned an invalid IssuedToken.");
 88	  }
 89	
 90	  return requireNonEmptyString(value["token"], "IssuedToken.token");
 91	}
