 93	async function readBrokerError(response: Response): Promise<GitHubAppTokenBrokerError> {
 94	  let body: unknown;
 95	
 96	  try {
 97	    body = await response.json();
 98	  } catch {
 99	    return new GitHubAppTokenBrokerError(response.status, "invalid_response");
100	  }
101	
102	  if (!isRecord(body)) {
103	    return new GitHubAppTokenBrokerError(response.status, "invalid_response");
104	  }
105	
106	  const error = body["error"];
107	  const descriptionValue = body["error_description"];
108	  const code = typeof error === "string" && error.length > 0 ? error : "invalid_response";
109	  const description =
110	    typeof descriptionValue === "string" && descriptionValue.length > 0
111	      ? descriptionValue
112	      : undefined;
113	
114	  return new GitHubAppTokenBrokerError(response.status, code, description);
115	}
