import {
  GitHubAppTokenBrokerError,
  requestGitHubAppInstallationToken,
} from "@cyspbot/cyspbot/github-app-token";
import { describe, expect, it } from "vitest";

const workloadIdentityAudience = "https://cyspbot.local";
const brokerTokenEndpoint = "https://github-app-token-broker-local/token";
const resource = "https://api.github.com/repos/chikachow/cyspbot";
const scope = "contents:read";
const workloadIdentityToken = "eyJ.test.workload.identity";

describe("cyspbot OAuth Token Exchange Client", () => {
  it("uses the Workload Identity RPC binding before calling the broker", async () => {
    const events: string[] = [];
    let audience: string | undefined;
    const { env } = createEnv({
      onIssuerCall(value) {
        audience = value;
        events.push("issuer");
      },
      onBrokerCall() {
        events.push("broker");
      },
    });

    await requestGitHubAppInstallationToken(env, { resource, scope });

    expect(events).toEqual(["issuer", "broker"]);
    expect(audience).toBe(workloadIdentityAudience);
  });

  it("rejects a generated service binding without the RPC method", async () => {
    const { env } = createEnv({
      issuer: createGeneratedServiceBinding(),
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      "WORKLOAD_IDENTITY_ISSUER must expose issueToken()",
    );
  });

  it("returns a typed installation access token after the OAuth exchange", async () => {
    const requests: Array<{ input: RequestInfo | URL; init: RequestInit | undefined }> = [];
    const { env } = createEnv({
      onBrokerCall(input, init) {
        requests.push({ init, input });
      },
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).resolves.toEqual({
      accessToken: "ghs_test_token",
      expiresIn: 300,
      scope,
    });

    expect(requests).toHaveLength(1);
    expect(requests[0]?.input).toBe(brokerTokenEndpoint);
    expect(requests[0]?.init?.method).toBe("POST");
    expect(requests[0]?.init?.redirect).toBe("manual");
    expect(new Headers(requests[0]?.init?.headers).get("accept")).toBe("application/json");
    expect(new Headers(requests[0]?.init?.headers).get("content-type")).toBe(
      "application/x-www-form-urlencoded",
    );

    const requestBody = requests[0]?.init?.body;
    if (!(requestBody instanceof URLSearchParams)) {
      throw new TypeError("expected a URLSearchParams token-exchange body");
    }

    expect(Object.fromEntries(requestBody)).toEqual({
      grant_type: "urn:ietf:params:oauth:grant-type:token-exchange",
      requested_token_type: "urn:ietf:params:oauth:token-type:access_token",
      resource,
      scope,
      subject_token: workloadIdentityToken,
      subject_token_type: "urn:ietf:params:oauth:token-type:id_token",
    });
  });

  it.each([
    ["issued token type", { issued_token_type: "urn:example:token" }, "invalid issued token type"],
    ["token type", { token_type: "DPoP" }, "invalid token type"],
    ["expiration", { expires_in: 1.5 }, "invalid expiration"],
  ] as const)("rejects a success response with an invalid %s", async (_name, override, message) => {
    const { env } = createEnv({ response: createBrokerSuccessResponse(override) });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      message,
    );
  });

  it("does not contact either binding when the request is empty", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const { env } = createEnv({
      onIssuerCall() {
        issuerCalls += 1;
      },
      onBrokerCall() {
        brokerCalls += 1;
      },
    });

    await expect(requestGitHubAppInstallationToken(env, { resource: "", scope })).rejects.toThrow(
      "resource must be a non-empty string",
    );
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("does not contact the broker when the issuer returns no token", async () => {
    let brokerCalls = 0;
    const { env } = createEnv({
      issuerToken: { token: "" },
      onBrokerCall() {
        brokerCalls += 1;
      },
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      "IssuedToken.token must be a non-empty string",
    );
    expect(brokerCalls).toBe(0);
  });

  it("requires a non-empty scope before contacting either binding", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const { env } = createEnv({
      onIssuerCall() {
        issuerCalls += 1;
      },
      onBrokerCall() {
        brokerCalls += 1;
      },
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope: " " })).rejects.toThrow(
      "scope must be a non-empty string",
    );
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("throws a typed error for broker OAuth failures", async () => {
    const { env } = createEnv({
      response: new Response(
        JSON.stringify({ error: "invalid_scope", error_description: "scope is not permitted" }),
        { headers: { "content-type": "application/json" }, status: 400 },
      ),
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toEqual(
      expect.objectContaining({
        message: "GitHub App token broker returned 400: invalid_scope",
        name: "GitHubAppTokenBrokerError",
        oauthErrorCode: "invalid_scope",
        oauthErrorDescription: "scope is not permitted",
        status: 400,
      } satisfies Partial<GitHubAppTokenBrokerError>),
    );
  });
});

interface TestOptions {
  readonly issuer?: unknown;
  readonly issuerToken?: unknown;
  readonly onBrokerCall?: (input: RequestInfo | URL, init: RequestInit | undefined) => void;
  readonly onIssuerCall?: (audience: string) => void;
  readonly response?: Response;
}

function createEnv(options: TestOptions = {}): { env: CyspbotEnv } {
  const issuer =
    options.issuer ??
    createWorkloadIdentityIssuer((audience) => {
      options.onIssuerCall?.(audience);
      return options.issuerToken ?? { token: workloadIdentityToken };
    });

  return {
    env: {
      GITHUB_APP_TOKEN_BROKER: {
        ...createGeneratedServiceBinding(),
        fetch(input, init) {
          options.onBrokerCall?.(input, init);
          return Promise.resolve(options.response ?? createBrokerSuccessResponse());
        },
      },
      GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT: brokerTokenEndpoint,
      WORKLOAD_IDENTITY_ISSUER: issuer,
      WORKLOAD_IDENTITY_TOKEN_AUDIENCE: workloadIdentityAudience,
    },
  };
}

function createBrokerSuccessResponse(overrides: Record<string, unknown> = {}) {
  return new Response(
    JSON.stringify({
      access_token: "ghs_test_token",
      expires_in: 300,
      issued_token_type: "urn:ietf:params:oauth:token-type:access_token",
      scope,
      token_type: "Bearer",
      ...overrides,
    }),
    { headers: { "content-type": "application/json" }, status: 200 },
  );
}

function createGeneratedServiceBinding() {
  return {
    connect() {
      throw new Error("service binding connect() is not used by this test");
    },
    fetch() {
      return Promise.resolve(new Response(null, { status: 501 }));
    },
  };
}

function createWorkloadIdentityIssuer(issueToken: (audience: string) => unknown) {
  return {
    ...createGeneratedServiceBinding(),
    issueToken: (audience: string) => Promise.resolve(issueToken(audience)),
  };
}
# Implementation

## Workspace layout

cyspbot is a pnpm workspace with two deployable Cloudflare Workers:

- `workers/cyspbot` publishes `@cyspbot/cyspbot` and Worker `cyspbot`.
- `workers/cyspbot-github-webhook-receiver` publishes `@cyspbot/github-webhook-receiver` and Worker `cyspbot-github-webhook-receiver`.

Shared packages:

- `packages/http` provides bounded body reading, request-body handling, JSON responses, and problem-details responses.
- `packages/github` provides the string-or-Secrets-Store secret-binding adapter used by webhook verification.

The root `wrangler.jsonc` points at `test/support/root-test-harness.ts`. It supplies common bindings to unit tests and is not a deployable product Worker.

## Root Worker flow

`workers/cyspbot/src/worker.ts` uses Hono's tiny preset. Its `GET /` route returns the minimal HTML bot page; Hono maps `HEAD /` to that route and removes the body. Hono's method-not-allowed middleware returns an empty `405` response with `Allow: GET, HEAD` for other methods at `/`, and the custom not-found handler returns an empty `404` response for every other pathname. Query parameters do not change route matching.

In production, this Worker is the Custom Domain origin. More specific Cloudflare Worker Routes execute first and preserve independently deployed product endpoints such as `/github/webhooks`.

## Webhook Worker flow

`workers/cyspbot-github-webhook-receiver/src/worker.ts` exposes only `POST /github/webhooks`. It rejects unknown routes and other methods before calling `handleGitHubWebhookRequest`.

`acceptGitHubWebhookDelivery` then:

1. resolves `GITHUB_WEBHOOK_SECRET` from a direct Worker secret or Secrets Store binding;
2. requires `application/json` and reads at most `256 KiB`;
3. requires the event, delivery, signature, and installation-target headers;
4. requires the target type `integration` and the configured `GITHUB_APP_ID`;
5. verifies the exact bytes with HMAC-SHA256;
6. parses the authenticated body as JSON; and
7. returns the acknowledgement shape for ping or other events.

The operation does not retain bodies, deduplicate delivery IDs, or dispatch event-specific handlers.

## Runtime bindings

- `GITHUB_APP_ID`: required non-secret variable used to bind deliveries to the intended GitHub App.
- `GITHUB_WEBHOOK_SECRET`: required Worker secret or Cloudflare Secrets Store binding.
- `WORKLOAD_IDENTITY_ISSUER`: RPC Service Binding to a separately deployed
  `WorkloadIdentityIssuer` entrypoint. Its `issueToken(audience)` operation
  returns an `IssuedToken`; the issuer deployment owns the workload subject
  and signing details. This RPC is a workload-identity interface, not an OAuth
  token endpoint.
- `WORKLOAD_IDENTITY_TOKEN_AUDIENCE`: non-secret Worker variable containing the
  logical audience requested from the issuer and accepted by the broker.
- `GITHUB_APP_TOKEN_BROKER`: Service Binding used by the OAuth Client to call
  the broker's existing RFC 8693 Token Endpoint with `fetch`.
- `GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT`: non-secret Worker variable
  containing the broker's token endpoint URL. It is separate from the logical
  Workload Identity Token audience.

The internal Token Exchange Client first calls the issuer RPC, then posts the
returned short-lived Workload Identity Token as a workload identity assertion
to the configured broker endpoint as the RFC 8693 `subject_token` under the
broker's OIDC ID Token subject-token profile. It requests a GitHub App
Installation Access Token with a canonical GitHub `resource` and explicit permission
`scope`; the broker remains the source of truth for normalization, OIDC ID
Token profile verification, and Token Issuance Policy. On success, the client
returns a `GitHubAppInstallationAccessToken`. On an OAuth failure, it throws a
`GitHubAppTokenBrokerError` containing the HTTP status and OAuth error code and
description. Workload identity assertions and issued GitHub tokens must not be
logged.

The client is an internal library operation and is not exposed as an HTTP
route. Production service names, identity properties, domains, routes,
resource identifiers, secret-store references, and Cloudflare Workload Identity
properties belong to the separate deployment repository. The public Worker
Wrangler files contain only local-development and dry-run service targets and
values.

## Tests and validation

The unit project exercises the root response, empty fallback response, bounded body reading, request-body size and status handling, signature/target validation, response mapping, and both Worker factories. Separate Workerd integration projects load each Worker's real Wrangler configuration and entrypoint.

The cyspbot integration project supplies a fetch-only `501` placeholder for
`WORKLOAD_IDENTITY_ISSUER` because the local harness resolves configured
service bindings during startup but cannot instantiate the separately deployed
named entrypoint. The root handler does not invoke that binding. The client
tests use a structural fixture for the named-entrypoint method and validate the
`IssuedToken` boundary; they do not test the deployed RPC implementation.

Use Node 24 and the pinned pnpm version:

```bash
fnm exec --using=24 corepack pnpm run check
fnm exec --using=24 corepack pnpm run test:coverage
```

`check` verifies the frozen lockfile, formatting, generated environment types, lint, TypeScript, Knip, unit and integration tests, and both Workers' Wrangler deploy dry runs.
