  3	const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
  4	const requestedTokenType = "urn:ietf:params:oauth:token-type:access_token";
  5	const subjectTokenType = "urn:ietf:params:oauth:token-type:id_token";
  6	const accessTokenScheme = "Bearer";
  7	const maxBrokerResponseBytes = 64 * 1024;
  8	const maxOAuthErrorDescriptionLength = 1024;
  9	
 10	export interface GitHubAppInstallationTokenRequest {
 11	  /** Canonical GitHub API Repository Resource where the token will be used. */
 12	  readonly resource: string;
 13	  /** Explicit GitHub App permission requests, in the broker's scope syntax. */
 14	  readonly scope: string;
 15	}
 16	
 17	export interface GitHubAppInstallationAccessToken {
 18	  readonly accessToken: string;
 19	  readonly expiresIn: number;
 20	  readonly scope: string;
 21	}
 22	
 23	export class GitHubAppTokenBrokerError extends Error {
 24	  readonly status: number;
 25	  readonly oauthErrorCode: string;
 26	  readonly oauthErrorDescription: string | undefined;
 27	
 28	  constructor(status: number, oauthErrorCode: string, oauthErrorDescription?: string) {
 29	    super(`GitHub App token broker returned ${status}: ${oauthErrorCode}`);
 30	    this.name = "GitHubAppTokenBrokerError";
 31	    this.status = status;
 32	    this.oauthErrorCode = oauthErrorCode;
 33	    this.oauthErrorDescription = oauthErrorDescription;
 34	  }
 35	}
 36	
 37	interface WorkloadIdentityIssuerBinding {
 38	  issueToken(audience: string): Promise<unknown>;
 39	}
 40	
 41	/**
 42	 * Obtains a Workload Identity Token, then exchanges it for a GitHub App
 43	 * Installation Access Token through the broker's RFC 8693 Token Endpoint.
 44	 */
 45	export async function requestGitHubAppInstallationToken(
 46	  env: CyspbotEnv,
 47	  request: GitHubAppInstallationTokenRequest,
 48	): Promise<GitHubAppInstallationAccessToken> {
 49	  const resource = requireNonEmptyString(request.resource, "resource");
 50	  const scope = requireNonEmptyString(request.scope, "scope");
 51	  const issuer = requireWorkloadIdentityIssuer(env.WORKLOAD_IDENTITY_ISSUER);
 52	  const issuedToken = await issuer.issueToken(env.WORKLOAD_IDENTITY_TOKEN_AUDIENCE);
 53	  const subjectToken = requireIssuedToken(issuedToken);
 54	
 55	  const response = await env.GITHUB_APP_TOKEN_BROKER.fetch(
 56	    env.GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT,
 57	    {
 58	      body: new URLSearchParams({
 59	        grant_type: tokenExchangeGrantType,
 60	        requested_token_type: requestedTokenType,
 61	        resource,
 62	        scope,
 63	        subject_token: subjectToken,
 64	        subject_token_type: subjectTokenType,
 65	      }),
 66	      headers: {
 67	        accept: "application/json",
 68	        "content-type": "application/x-www-form-urlencoded",
 69	      },
 70	      method: "POST",
 71	      redirect: "manual",
 72	    },
 73	  );
 74	
 75	  if (!response.ok) {
 76	    throw await readBrokerError(response);
 77	  }
 78	
 79	  return readInstallationAccessToken(response);
 80	}
 81	
 82	function requireWorkloadIdentityIssuer(value: unknown): WorkloadIdentityIssuerBinding {
 83	  if (!isWorkloadIdentityIssuerBinding(value)) {
 84	    throw new TypeError("WORKLOAD_IDENTITY_ISSUER must expose issueToken().");
 85	  }
 86	
 87	  return value;
 88	}
 89	
 90	function requireIssuedToken(value: unknown): string {
 91	  if (!isRecord(value)) {
 92	    throw new TypeError("WORKLOAD_IDENTITY_ISSUER returned an invalid IssuedToken.");
 93	  }
 94	
 95	  return requireNonEmptyString(value["token"], "IssuedToken.token");
 96	}
 97	
 98	async function readBrokerError(response: Response): Promise<GitHubAppTokenBrokerError> {
 99	  const body = await readJsonBody(response);
100	
101	  if (!isRecord(body)) {
102	    return new GitHubAppTokenBrokerError(response.status, "invalid_response");
103	  }
104	
105	  const error = body["error"];
106	  const descriptionValue = body["error_description"];
107	  const code = typeof error === "string" && error.length > 0 ? error : "invalid_response";
108	  const description =
109	    typeof descriptionValue === "string" &&
110	    descriptionValue.length > 0 &&
111	    descriptionValue.length <= maxOAuthErrorDescriptionLength
112	      ? descriptionValue
113	      : undefined;
114	
115	  return new GitHubAppTokenBrokerError(response.status, code, description);
116	}
117	
118	async function readInstallationAccessToken(
119	  response: Response,
120	): Promise<GitHubAppInstallationAccessToken> {
121	  const body = await readJsonBody(response);
122	
123	  if (!isRecord(body)) {
124	    throw new TypeError("GitHub App token broker returned an invalid token response.");
125	  }
126	
127	  const expiresIn = body["expires_in"];
128	  if (typeof expiresIn !== "number" || !Number.isInteger(expiresIn) || expiresIn <= 0) {
129	    throw new TypeError("GitHub App token broker returned an invalid expiration.");
130	  }
131	
132	  if (body["issued_token_type"] !== requestedTokenType) {
133	    throw new TypeError("GitHub App token broker returned an invalid issued token type.");
134	  }
135	
136	  if (body["token_type"] !== accessTokenScheme) {
137	    throw new TypeError("GitHub App token broker returned an invalid token type.");
138	  }
139	
140	  return {
141	    accessToken: requireNonEmptyString(body["access_token"], "access_token"),
142	    expiresIn,
143	    scope: requireNonEmptyString(body["scope"], "scope"),
144	  };
145	}
146	
147	async function readJsonBody(response: Response): Promise<unknown> {
148	  const body = await readBodyUpTo(response.body, maxBrokerResponseBytes);
149	
150	  if (!body.ok) {
151	    return undefined;
152	  }
153	
154	  try {
155	    return JSON.parse(new TextDecoder().decode(body.bytes));
156	  } catch {
157	    return undefined;
158	  }
159	}
160	
161	function isWorkloadIdentityIssuerBinding(value: unknown): value is WorkloadIdentityIssuerBinding {
162	  return isRecord(value) && typeof value["issueToken"] === "function";
163	}
164	
165	function isRecord(value: unknown): value is Record<string, unknown> {
166	  return typeof value === "object" && value !== null;
167	}
168	
169	function requireNonEmptyString(value: unknown, name: string): string {
170	  if (typeof value !== "string" || value.trim().length === 0) {
171	    throw new TypeError(`${name} must be a non-empty string.`);
172	  }
173	
174	  return value;
175	}
