169	interface TestOptions {
170	  readonly issuer?: TestIssuer;
171	  readonly issuerToken?: unknown;
172	  readonly onBrokerCall?: (input: RequestInfo | URL, init: RequestInit | undefined) => void;
173	  readonly onIssuerCall?: (audience: string) => void;
174	  readonly response?: Response;
175	}
176	
177	function createEnv(options: TestOptions = {}): { env: CyspbotEnv } {
178	  const issuer =
179	    options.issuer ??
